#include "g++-2/stl_vector_shared.h"

typedef float rational_t;

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;

  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
  inline vector3d& operator = (const vector3d& v)
  { x = v.x; y = v.y; z = v.z; return *this; }
};

template <class _Tp, class _Alloc>
void vector<_Tp, _Alloc>::insert(iterator __position, unsigned int __n,
                                 const _Tp& __x)
{
  if (__n != 0) {
    if (unsigned int(_M_end_of_storage - _M_finish) >= __n) {
      _Tp __x_copy = __x;
      const unsigned int __elems_after = _M_finish - __position;
      iterator __old_finish = _M_finish;
      if (__elems_after > __n) {
        uninitialized_copy(_M_finish - __n, _M_finish, _M_finish);
        _M_finish += __n;
        copy_backward(__position, __old_finish - __n, __old_finish);
        fill(__position, __position + __n, __x_copy);
      }
      else {
        uninitialized_fill_n(_M_finish, __n - __elems_after, __x_copy);
        _M_finish += __n - __elems_after;
        uninitialized_copy(__position, __old_finish, _M_finish);
        _M_finish += __elems_after;
        fill(__position, __old_finish, __x_copy);
      }
    }
    else {
      const unsigned int __old_size = size();
      const unsigned int __len = __old_size + max(__old_size, __n);
      iterator __new_start = _M_allocate(__len);
      iterator __new_finish = __new_start;
      __new_finish = uninitialized_copy(_M_start, __position, __new_start);
      __new_finish = uninitialized_fill_n(__new_finish, __n, __x);
      __new_finish
        = uninitialized_copy(__position, _M_finish, __new_finish);
      destroy(_M_start, _M_finish);
      _M_deallocate(_M_start, _M_end_of_storage - _M_start);
      _M_start = __new_start;
      _M_finish = __new_finish;
      _M_end_of_storage = __new_start + __len;
    }
  }
}

template void vector<vector3d, my_allocator<vector3d> >::insert(
    vector3d *, unsigned int, const vector3d &);
